export const FACTS: FactItem[] = [
  // ---- Glycolysis & Gluconeogenesis ----
  { id: 'gly-1', topicId: 'glycolysis', fact: 'Phosphofructokinase-1 (PFK-1) is the rate-limiting enzyme of glycolysis and is inhibited by ATP and citrate, activated by AMP and fructose-2,6-bisphosphate.', question: 'What is the rate-limiting enzyme of glycolysis?', answer: 'Phosphofructokinase-1 (PFK-1) — inhibited by ATP/citrate, activated by AMP and fructose-2,6-bisphosphate.' },
  { id: 'gly-2', topicId: 'glycolysis', fact: 'Glycolysis has three irreversible, regulated steps: hexokinase/glucokinase, PFK-1, and pyruvate kinase — these are the same three steps gluconeogenesis must bypass.', question: 'Which three glycolytic steps are irreversible, and why does this matter for gluconeogenesis?', answer: 'Hexokinase/glucokinase, PFK-1, and pyruvate kinase — gluconeogenesis needs separate bypass enzymes at each of these three steps.' },
  { id: 'gly-3', topicId: 'glycolysis', fact: 'Glucokinase (liver, beta cells) has a high Km for glucose and is not inhibited by glucose-6-phosphate, unlike hexokinase (most tissues), which has a low Km and is product-inhibited.', question: 'How does glucokinase differ from hexokinase?', answer: 'Glucokinase: high Km, not product-inhibited, liver/beta cells. Hexokinase: low Km, inhibited by G6P, most other tissues.' },
  { id: 'gly-4', topicId: 'glycolysis', fact: 'Fructose-1,6-bisphosphatase, the key gluconeogenesis regulatory enzyme, is inhibited by fructose-2,6-bisphosphate and AMP — the mirror image of PFK-1 regulation.', question: 'What inhibits fructose-1,6-bisphosphatase in gluconeogenesis?', answer: 'Fructose-2,6-bisphosphate and AMP.' },
  { id: 'gly-5', topicId: 'glycolysis', fact: 'Pyruvate carboxylase (biotin-dependent) converts pyruvate to oxaloacetate in mitochondria — the first step of gluconeogenesis, and it requires acetyl-CoA as an allosteric activator.', question: 'Which biotin-dependent enzyme starts gluconeogenesis from pyruvate, and what activates it?', answer: 'Pyruvate carboxylase, activated allosterically by acetyl-CoA.' },
  { id: 'gly-6', topicId: 'glycolysis', fact: 'Arsenic poisoning blocks glyceraldehyde-3-phosphate dehydrogenase by substituting arsenate for phosphate, uncoupling substrate-level phosphorylation without stopping the reaction — net ATP loss.', question: 'How does arsenic disrupt glycolysis?', answer: 'It substitutes for phosphate in the GAPDH reaction, forming an unstable product that skips the ATP-generating step — net loss of ATP yield.' },
  { id: 'gly-7', topicId: 'glycolysis', fact: 'Pyruvate kinase deficiency is the most common enzyme defect causing hereditary non-spherocytic hemolytic anemia, since RBCs depend entirely on glycolysis for ATP.', question: 'What is the most common glycolytic enzyme deficiency causing hemolytic anemia?', answer: 'Pyruvate kinase deficiency — RBCs have no mitochondria and rely solely on glycolysis for ATP.' },
  { id: 'gly-8', topicId: 'glycolysis', fact: 'The Cori cycle shuttles lactate from muscle (produced anaerobically) to the liver, where it is converted back to glucose via gluconeogenesis and returned to muscle.', question: 'What is the Cori cycle?', answer: 'Muscle lactate → liver → glucose (gluconeogenesis) → back to muscle. Shifts the ATP cost of gluconeogenesis to the liver.' },
  { id: 'gly-9', topicId: 'glycolysis', fact: 'The Warburg effect describes how cancer cells preferentially use aerobic glycolysis (fermenting glucose to lactate even with adequate oxygen) rather than oxidative phosphorylation, favoring rapid ATP and biosynthetic precursor production over efficiency.', question: 'What is the Warburg effect?', answer: 'Cancer cells favor aerobic glycolysis (lactate production despite adequate O2) over oxidative phosphorylation, prioritizing speed and biosynthetic intermediates over ATP yield.' },
  { id: 'gly-10', topicId: 'glycolysis', fact: '2,3-Bisphosphoglycerate (2,3-BPG), made from a glycolytic side branch (Rapoport-Luebering shunt), binds deoxyhemoglobin and lowers its oxygen affinity, shifting the oxygen dissociation curve right and promoting O2 unloading in tissues.', question: 'What does 2,3-BPG do to the oxygen-hemoglobin dissociation curve?', answer: 'Shifts it right, decreasing hemoglobin oxygen affinity and promoting O2 release to tissues.' },
  { id: 'gly-11', topicId: 'glycolysis', fact: 'Lactate dehydrogenase (LDH) exists as tissue-specific isoenzymes; LDH-1 predominates in heart/RBCs and LDH-5 in liver/skeletal muscle, historically used to help localize tissue damage (e.g. LDH-1 > LDH-2 flip in MI).', question: 'Which LDH isoenzyme predominates in cardiac tissue?', answer: 'LDH-1.' },

  // ---- TCA Cycle & ETC ----
  { id: 'tca-1', topicId: 'tca-etc', fact: 'Isocitrate dehydrogenase is the rate-limiting enzyme of the TCA cycle, inhibited by ATP and NADH, activated by ADP.', question: 'What is the rate-limiting enzyme of the TCA cycle?', answer: 'Isocitrate dehydrogenase.' },
  { id: 'tca-2', topicId: 'tca-etc', fact: 'The pyruvate dehydrogenase complex requires five cofactors: thiamine pyrophosphate (B1), lipoic acid, CoA (B5), FAD (B2), and NAD+ (B3) — remembered as "Tender Loving Care For Nancy."', question: 'What five cofactors does pyruvate dehydrogenase require?', answer: 'TPP (B1), lipoic acid, CoA (B5), FAD (B2), NAD+ (B3).' },
  { id: 'tca-3', topicId: 'tca-etc', fact: 'Arsenic and mercury poison pyruvate dehydrogenase and alpha-ketoglutarate dehydrogenase by inactivating their lipoic acid cofactor.', question: 'Which cofactor do arsenic/mercury poison in the PDH and alpha-KG dehydrogenase complexes?', answer: 'Lipoic acid.' },
  { id: 'tca-4', topicId: 'tca-etc', fact: 'Complex I (NADH dehydrogenase) and Complex III are the two sites the electron transport chain pumps protons at along with Complex IV; each NADH yields roughly 2.5 ATP and each FADH2 roughly 1.5 ATP.', question: 'Roughly how much ATP does one NADH vs one FADH2 yield via oxidative phosphorylation?', answer: 'NADH ≈ 2.5 ATP; FADH2 ≈ 1.5 ATP (FADH2 enters at Complex II, bypassing Complex I).' },
  { id: 'tca-5', topicId: 'tca-etc', fact: 'Cyanide and carbon monoxide both block Complex IV (cytochrome c oxidase), halting oxidative phosphorylation entirely.', question: 'Which ETC complex do cyanide and CO block?', answer: 'Complex IV (cytochrome c oxidase).' },
  { id: 'tca-6', topicId: 'tca-etc', fact: '2,4-Dinitrophenol (DNP) is a classic uncoupler — it dissipates the proton gradient across the inner mitochondrial membrane without ATP synthase, so oxidation continues but no ATP is made and heat is released instead.', question: 'What does an uncoupler like 2,4-dinitrophenol do?', answer: 'Dissipates the H+ gradient without going through ATP synthase — electron transport and O2 consumption continue, but energy is released as heat instead of ATP.' },
  { id: 'tca-7', topicId: 'tca-etc', fact: 'Brown adipose tissue naturally uncouples oxidative phosphorylation via UCP1 (thermogenin) for non-shivering thermogenesis in infants.', question: 'What is the physiological uncoupling protein in brown fat called?', answer: 'UCP1 (thermogenin).' },
  { id: 'tca-8', topicId: 'tca-etc', fact: 'Oligomycin inhibits ATP synthase (Complex V) directly by blocking its proton channel — unlike an uncoupler, this also stops electron transport indirectly, since the proton gradient backs up with nowhere to go.', question: 'How does oligomycin differ functionally from an uncoupler like DNP?', answer: 'Oligomycin blocks ATP synthase directly, which backs up the proton gradient and secondarily halts electron transport; an uncoupler dissipates the gradient so electron transport continues without ATP production.' },
  { id: 'tca-9', topicId: 'tca-etc', fact: 'Anaplerotic reactions replenish TCA cycle intermediates drained for biosynthesis — pyruvate carboxylase (making oxaloacetate) is the most important anaplerotic reaction.', question: 'What is an anaplerotic reaction, and give its classic example.', answer: 'A reaction that replenishes TCA cycle intermediates; pyruvate carboxylase converting pyruvate to oxaloacetate is the classic example.' },
  { id: 'tca-10', topicId: 'tca-etc', fact: 'The malate-aspartate shuttle transfers cytosolic NADH electrons into mitochondria with no energy loss (yielding ~2.5 ATP per NADH, used in heart/liver/kidney); the glycerol-3-phosphate shuttle loses some energy, yielding only ~1.5 ATP per cytosolic NADH (used in skeletal muscle/brain).', question: 'Which electron shuttle is more energy-efficient, and where is it used?', answer: 'The malate-aspartate shuttle (yields ~2.5 ATP/NADH) — used in heart, liver, and kidney. The glycerol-3-phosphate shuttle is less efficient (~1.5 ATP) and used in skeletal muscle and brain.' },

  // ---- Glycogen & HMP shunt ----
  { id: 'gly2-1', topicId: 'glycogen-hmp', fact: 'Glycogen phosphorylase is the rate-limiting enzyme of glycogenolysis; it is activated by glucagon/epinephrine (via PKA) and by AMP in muscle, inhibited by ATP and glucose.', question: 'What is the rate-limiting enzyme of glycogen breakdown, and what activates it?', answer: 'Glycogen phosphorylase — activated by glucagon/epinephrine (via cAMP/PKA) and AMP.' },
  { id: 'gly2-2', topicId: 'glycogen-hmp', fact: 'Von Gierke disease (type I glycogen storage disease) is due to glucose-6-phosphatase deficiency, causing severe fasting hypoglycemia, lactic acidosis, and hepatomegaly.', question: 'Which enzyme is deficient in Von Gierke disease, and what is the hallmark presentation?', answer: 'Glucose-6-phosphatase — severe fasting hypoglycemia, lactic acidosis, hepatomegaly.' },
  { id: 'gly2-3', topicId: 'glycogen-hmp', fact: "Pompe disease (type II GSD) is caused by lysosomal alpha-1,4-glucosidase (acid maltase) deficiency, presenting with cardiomegaly and is the only GSD that is fatal via heart failure.", question: 'Which glycogen storage disease classically causes cardiomegaly?', answer: 'Pompe disease (acid alpha-glucosidase/acid maltase deficiency).' },
  { id: 'gly2-4', topicId: 'glycogen-hmp', fact: 'The HMP (pentose phosphate) shunt has two irreversible oxidative steps producing NADPH, catalyzed by glucose-6-phosphate dehydrogenase (rate-limiting) and 6-phosphogluconate dehydrogenase.', question: 'What is the rate-limiting enzyme of the HMP shunt, and what does it produce?', answer: 'Glucose-6-phosphate dehydrogenase (G6PD) — produces NADPH.' },
  { id: 'gly2-5', topicId: 'glycogen-hmp', fact: 'G6PD deficiency causes hemolytic anemia under oxidative stress (e.g. fava beans, sulfa drugs, antimalarials) due to insufficient NADPH to regenerate reduced glutathione, forming Heinz bodies.', question: 'Why does G6PD deficiency cause hemolysis under oxidative stress?', answer: 'Insufficient NADPH means glutathione cannot be regenerated to reduced form, so RBCs cannot neutralize peroxide — leads to Heinz body formation and hemolysis.' },
  { id: 'gly2-6', topicId: 'glycogen-hmp', fact: 'NADPH from the HMP shunt is essential for fatty acid/cholesterol synthesis, glutathione reduction, and the respiratory burst (NADPH oxidase) in phagocytes.', question: 'Name three major uses of NADPH in the body.', answer: 'Reductive biosynthesis (fatty acids, cholesterol), glutathione regeneration, and the phagocyte respiratory burst.' },
  { id: 'gly2-7', topicId: 'glycogen-hmp', fact: 'Glycogen synthase, the rate-limiting enzyme of glycogen synthesis, is activated by insulin and inhibited by glucagon/epinephrine — the reciprocal regulation of glycogen phosphorylase, so the two pathways are never both fully active at once.', question: 'What is the rate-limiting enzyme of glycogen synthesis, and how is it regulated relative to glycogen phosphorylase?', answer: 'Glycogen synthase — activated by insulin, inhibited by glucagon/epinephrine, reciprocal to glycogen phosphorylase regulation.' },
  { id: 'gly2-8', topicId: 'glycogen-hmp', fact: "Cori disease (type III GSD, debranching enzyme deficiency) resembles a milder Von Gierke disease — fasting hypoglycemia but with normal lactate levels (unlike Von Gierke's lactic acidosis), since gluconeogenesis remains intact.", question: 'How does Cori disease (type III GSD) differ from Von Gierke disease (type I) despite both causing fasting hypoglycemia?', answer: 'Cori disease has normal lactate (gluconeogenesis intact, debranching enzyme deficient); Von Gierke has lactic acidosis (glucose-6-phosphatase deficient, gluconeogenesis output blocked).' },
  { id: 'gly2-9', topicId: 'glycogen-hmp', fact: 'UDP-glucose, formed from glucose-1-phosphate by UDP-glucose pyrophosphorylase, is the activated glucose donor used by glycogen synthase to extend glycogen chains.', question: 'What is the immediate glucose donor molecule used by glycogen synthase?', answer: 'UDP-glucose.' },

  // ---- Lipid Metabolism ----
  { id: 'lip-1', topicId: 'lipid', fact: 'Carnitine acyltransferase I (CPT-I), located on the outer mitochondrial membrane, is the rate-limiting and regulated step of fatty acid beta-oxidation, and is inhibited by malonyl-CoA.', question: 'What inhibits CPT-I, the rate-limiting enzyme of beta-oxidation?', answer: 'Malonyl-CoA — this links fatty acid synthesis (which produces malonyl-CoA) to inhibition of fatty acid breakdown.' },
  { id: 'lip-2', topicId: 'lipid', fact: 'Acetyl-CoA carboxylase (ACC) is the rate-limiting enzyme of fatty acid synthesis, activated by citrate and insulin, inhibited by glucagon/epinephrine and its own product palmitoyl-CoA.', question: 'What is the rate-limiting enzyme of fatty acid synthesis?', answer: 'Acetyl-CoA carboxylase (ACC) — makes malonyl-CoA, activated by citrate/insulin, inhibited by glucagon and palmitoyl-CoA.' },
  { id: 'lip-3', topicId: 'lipid', fact: 'HMG-CoA reductase is the rate-limiting enzyme of cholesterol synthesis and the target of statin drugs.', question: 'Which enzyme do statins inhibit?', answer: 'HMG-CoA reductase, the rate-limiting step of cholesterol synthesis.' },
  { id: 'lip-4', topicId: 'lipid', fact: 'Ketone bodies (acetoacetate, beta-hydroxybutyrate) are made in liver mitochondria via HMG-CoA synthase during prolonged fasting or diabetic ketoacidosis, but the liver cannot use them because it lacks succinyl-CoA:3-ketoacid CoA transferase (thiophorase).', question: 'Why can the liver make ketone bodies but not use them for energy?', answer: 'It lacks thiophorase (succinyl-CoA:3-ketoacid CoA transferase), the enzyme needed to reactivate acetoacetate to acetoacetyl-CoA.' },
  { id: 'lip-5', topicId: 'lipid', fact: 'Chylomicrons carry dietary (exogenous) triglycerides from the intestine; VLDL carries endogenous triglycerides made by the liver; LDL delivers cholesterol to tissues; HDL performs reverse cholesterol transport back to the liver.', question: 'Match each lipoprotein to its main job: chylomicrons, VLDL, LDL, HDL.', answer: 'Chylomicrons = dietary fat transport; VLDL = liver-made triglyceride export; LDL = cholesterol delivery to tissues; HDL = reverse cholesterol transport.' },
  { id: 'lip-6', topicId: 'lipid', fact: 'Lipoprotein lipase, anchored on capillary endothelium and activated by apoC-II, hydrolyzes triglycerides in chylomicrons and VLDL for tissue uptake.', question: 'What activates lipoprotein lipase?', answer: 'ApoC-II.' },
  { id: 'lip-7', topicId: 'lipid', fact: 'Each round of beta-oxidation shortens a fatty acid by two carbons and generates one NADH, one FADH2, and one acetyl-CoA.', question: 'What are the three products of one round of beta-oxidation?', answer: 'One NADH, one FADH2, and one acetyl-CoA (plus a fatty acid shortened by 2 carbons).' },
  { id: 'lip-8', topicId: 'lipid', fact: 'Linoleic acid (omega-6) and alpha-linolenic acid (omega-3) are essential fatty acids that cannot be synthesized by the body and must come from diet, since humans lack the desaturase enzymes to introduce double bonds beyond carbon 9.', question: 'Why are linoleic and alpha-linolenic acid "essential" fatty acids?', answer: 'Humans lack the desaturase enzymes needed to insert double bonds beyond the 9th carbon from the carboxyl end, so these omega-6/omega-3 fatty acids must come from the diet.' },
  { id: 'lip-9', topicId: 'lipid', fact: 'Hormone-sensitive lipase, activated by glucagon/epinephrine via PKA and inhibited by insulin, mobilizes stored triglycerides from adipocytes into free fatty acids and glycerol.', question: 'What activates hormone-sensitive lipase in adipose tissue?', answer: 'Glucagon and epinephrine (via cAMP/PKA); insulin inhibits it.' },
  { id: 'lip-10', topicId: 'lipid', fact: 'ApoB-100 is the ligand LDL uses to bind the LDL receptor for hepatic/peripheral uptake; familial hypercholesterolemia results from LDL receptor mutations, causing very high LDL and early atherosclerosis.', question: 'Which apolipoprotein does the LDL receptor recognize, and what disease results from receptor mutations?', answer: 'ApoB-100; LDL receptor mutations cause familial hypercholesterolemia.' },

  // ---- Amino Acid Metabolism & Urea Cycle ----
  { id: 'aa-1', topicId: 'amino-acid', fact: 'Carbamoyl phosphate synthetase I (mitochondrial, ammonia-using) is the rate-limiting enzyme of the urea cycle, activated by N-acetylglutamate.', question: 'What activates carbamoyl phosphate synthetase I in the urea cycle?', answer: 'N-acetylglutamate.' },
  { id: 'aa-2', topicId: 'amino-acid', fact: 'The urea cycle occurs partly in mitochondria (carbamoyl phosphate synthetase I, ornithine transcarbamylase) and partly in cytosol (argininosuccinate synthetase, lyase, arginase).', question: 'Which two urea cycle enzymes are mitochondrial?', answer: 'Carbamoyl phosphate synthetase I and ornithine transcarbamylase.' },
  { id: 'aa-3', topicId: 'amino-acid', fact: 'Ornithine transcarbamylase (OTC) deficiency, the most common urea cycle disorder and X-linked, causes hyperammonemia with elevated orotic acid but normal citrulline (distinguishing it from carbamoyl phosphate synthetase deficiency).', question: 'Which urea cycle disorder causes hyperammonemia with high orotic acid but low citrulline?', answer: 'Ornithine transcarbamylase (OTC) deficiency — X-linked, the most common urea cycle disorder.' },
  { id: 'aa-4', topicId: 'amino-acid', fact: 'Alanine (from muscle) and glutamine (from most tissues) are the main carriers of amino groups to the liver for ureagenesis — the alanine (glucose-alanine) cycle mirrors the Cori cycle.', question: 'What are the two main amino-group carriers to the liver, and which amino acid mirrors the Cori cycle?', answer: 'Alanine and glutamine; alanine\'s glucose-alanine cycle mirrors the Cori cycle.' },
  { id: 'aa-5', topicId: 'amino-acid', fact: 'Phenylketonuria (PKU) results from phenylalanine hydroxylase deficiency (or its cofactor tetrahydrobiopterin), causing phenylalanine buildup, mental retardation if untreated, and a musty body odor.', question: 'What enzyme is deficient in PKU?', answer: 'Phenylalanine hydroxylase (or its cofactor BH4) — phenylalanine cannot be converted to tyrosine.' },
  { id: 'aa-6', topicId: 'amino-acid', fact: 'Homocystinuria is most commonly due to cystathionine beta-synthase deficiency, causing lens dislocation, marfanoid habitus, thrombosis, and intellectual disability — treatable in part with vitamin B6.', question: 'Which enzyme deficiency causes classic homocystinuria?', answer: 'Cystathionine beta-synthase (requires vitamin B6/pyridoxine as cofactor).' },
  { id: 'aa-7', topicId: 'amino-acid', fact: 'Maple syrup urine disease is caused by deficient branched-chain alpha-ketoacid dehydrogenase, blocking degradation of leucine, isoleucine, and valine, giving urine a sweet, burnt-sugar odor.', question: 'Which amino acids accumulate in maple syrup urine disease?', answer: 'Leucine, isoleucine, and valine (branched-chain amino acids) — due to branched-chain alpha-ketoacid dehydrogenase deficiency.' },
  { id: 'aa-8', topicId: 'amino-acid', fact: 'Alkaptonuria, a benign inborn error, is caused by homogentisate oxidase deficiency, causing dark urine on standing and later ochronosis (bluish-black cartilage/skin pigmentation).', question: 'What enzyme deficiency causes alkaptonuria?', answer: 'Homogentisate oxidase (in the tyrosine degradation pathway).' },
  { id: 'aa-9', topicId: 'amino-acid', fact: 'S-adenosylmethionine (SAM), formed from methionine and ATP, is the universal methyl donor for reactions like norepinephrine-to-epinephrine conversion and DNA/histone methylation; it becomes homocysteine after donating its methyl group.', question: 'What is the universal methyl donor in the body, and what is it converted to after use?', answer: 'S-adenosylmethionine (SAM) — becomes homocysteine after donating its methyl group.' },
  { id: 'aa-10', topicId: 'amino-acid', fact: 'Tyrosine is the precursor for three major products via separate pathways: catecholamines (dopamine, norepinephrine, epinephrine), melanin, and thyroid hormone — a single amino acid feeding remarkably different systems.', question: 'Name three major classes of molecules derived from tyrosine.', answer: 'Catecholamines, melanin, and thyroid hormone.' },
  { id: 'aa-11', topicId: 'amino-acid', fact: 'Histidine is decarboxylated (by histidine decarboxylase, using PLP/B6) to form histamine, the mediator of allergic and inflammatory responses released by mast cells and basophils.', question: 'Which amino acid is the precursor of histamine, and via which cofactor-dependent enzyme?', answer: 'Histidine, via histidine decarboxylase (requires vitamin B6/PLP).' },
  { id: 'aa-12', topicId: 'amino-acid', fact: 'ALT and AST are transaminases that transfer amino groups to alpha-ketoglutarate, forming glutamate — the first common step funneling most amino acid nitrogen toward ureagenesis.', question: 'What do ALT and AST (aminotransferases) actually do biochemically?', answer: 'Transfer an amino group from an amino acid to alpha-ketoglutarate, forming glutamate (and a keto acid) — the entry step for nitrogen into the urea cycle pathway.' },

  // ---- Vitamins & Coenzymes ----
  { id: 'vit-1', topicId: 'vitamins', fact: 'Thiamine (B1) deficiency causes Wernicke-Korsakoff syndrome (classic in alcoholics) and beriberi (wet = high-output cardiac failure, dry = peripheral neuropathy).', question: 'What are the two classic beriberi presentations of thiamine deficiency?', answer: 'Wet beriberi (high-output cardiac failure) and dry beriberi (peripheral neuropathy); also Wernicke-Korsakoff syndrome.' },
  { id: 'vit-2', topicId: 'vitamins', fact: 'Niacin (B3) can be synthesized from tryptophan using B6, B2, and iron; deficiency causes pellagra — the three Ds: dermatitis, diarrhea, dementia.', question: 'What is the classic triad of niacin deficiency (pellagra)?', answer: 'Dermatitis, diarrhea, dementia (the "3 Ds").' },
  { id: 'vit-3', topicId: 'vitamins', fact: 'Vitamin B12 (cobalamin) and folate (B9) deficiency both cause megaloblastic anemia, but only B12 deficiency causes neurological symptoms (subacute combined degeneration) because folate cannot substitute for B12 in the methylmalonyl-CoA mutase reaction.', question: 'How do you distinguish B12 vs folate deficiency clinically?', answer: 'Both cause megaloblastic anemia, but only B12 deficiency causes neurologic symptoms (subacute combined degeneration of the spinal cord) — folate deficiency does not.' },
  { id: 'vit-4', topicId: 'vitamins', fact: 'Elevated methylmalonic acid indicates B12 deficiency specifically (not folate), since B12 is a cofactor for methylmalonyl-CoA mutase while folate is not.', question: 'Which lab value distinguishes B12 from folate deficiency?', answer: 'Methylmalonic acid — elevated only in B12 deficiency.' },
  { id: 'vit-5', topicId: 'vitamins', fact: 'Vitamin B6 (pyridoxine, as PLP) is a cofactor for transamination reactions and for isoniazid metabolism — isoniazid therapy commonly causes B6 deficiency and peripheral neuropathy if not supplemented.', question: 'Which vitamin deficiency does isoniazid commonly cause?', answer: 'Vitamin B6 (pyridoxine) deficiency, causing peripheral neuropathy.' },
  { id: 'vit-6', topicId: 'vitamins', fact: 'Biotin is the coenzyme for carboxylation reactions (e.g. pyruvate carboxylase, acetyl-CoA carboxylase); raw egg white contains avidin, which binds biotin and can cause deficiency.', question: 'What causes biotin deficiency from diet, classically?', answer: 'Excess raw egg white — contains avidin, which binds and blocks biotin absorption.' },
  { id: 'vit-7', topicId: 'vitamins', fact: 'Vitamin C (ascorbate) is required for prolyl and lysyl hydroxylase in collagen synthesis; deficiency causes scurvy — bleeding gums, poor wound healing, corkscrew hairs.', question: 'What enzymes require vitamin C, and what deficiency disease results?', answer: 'Prolyl and lysyl hydroxylase (collagen synthesis) — deficiency causes scurvy.' },
  { id: 'vit-8', topicId: 'vitamins', fact: 'Vitamin K is required to gamma-carboxylate clotting factors II, VII, IX, X, and proteins C and S; warfarin works by inhibiting vitamin K epoxide reductase.', question: 'Which clotting factors depend on vitamin K?', answer: 'Factors II, VII, IX, X, and proteins C and S.' },
  { id: 'vit-9', topicId: 'vitamins', fact: 'Vitamin A (retinol) deficiency causes night blindness (rhodopsin needs 11-cis-retinal) and xerophthalmia; excess vitamin A is teratogenic and a classic cause of pseudotumor cerebri.', question: 'What deficiency and toxicity states are associated with vitamin A?', answer: 'Deficiency: night blindness, xerophthalmia. Toxicity: teratogenicity, pseudotumor cerebri (idiopathic intracranial hypertension).' },
  { id: 'vit-10', topicId: 'vitamins', fact: 'Vitamin D is activated by sequential hydroxylation: 25-hydroxylation in the liver, then 1-alpha-hydroxylation in the kidney (stimulated by PTH) to form active calcitriol, which raises serum calcium via increased gut absorption.', question: 'Where does vitamin D undergo its second, activating hydroxylation, and what stimulates it?', answer: 'The kidney (1-alpha-hydroxylation), stimulated by parathyroid hormone (PTH).' },
  { id: 'vit-11', topicId: 'vitamins', fact: 'Riboflavin (B2) deficiency causes angular stomatitis (cracks at mouth corners), cheilosis, and glossitis; it is the precursor for FAD and FMN, coenzymes central to the electron transport chain and beta-oxidation.', question: 'What are the classic clinical signs of riboflavin (B2) deficiency?', answer: 'Angular stomatitis, cheilosis, and glossitis.' },
  { id: 'vit-12', topicId: 'vitamins', fact: 'Vitamin E (tocopherol) is a lipid-soluble antioxidant protecting cell membranes from peroxidation; deficiency (rare, usually from fat malabsorption) causes hemolytic anemia and posterior column/spinocerebellar deficits.', question: "What is vitamin E's main biochemical role, and what does deficiency cause?", answer: 'A lipid-soluble antioxidant preventing membrane lipid peroxidation; deficiency causes hemolytic anemia and neurologic (ataxia) deficits.' },

  // ---- Enzymes & Kinetics ----
  { id: 'enz-1', topicId: 'enzymes', fact: 'Competitive inhibitors increase apparent Km but do not change Vmax; they can be overcome by increasing substrate concentration.', question: 'How does a competitive inhibitor affect Km and Vmax?', answer: 'Increases Km, Vmax unchanged — effect overcome by more substrate.' },
  { id: 'enz-2', topicId: 'enzymes', fact: 'Noncompetitive inhibitors decrease Vmax but do not change Km, since they bind a site other than the active site and cannot be overcome by more substrate.', question: 'How does a noncompetitive inhibitor affect Km and Vmax?', answer: 'Vmax decreases, Km unchanged.' },
  { id: 'enz-3', topicId: 'enzymes', fact: 'Lineweaver-Burk plots (1/V vs 1/[S]) linearize Michaelis-Menten kinetics; the x-intercept is -1/Km and the y-intercept is 1/Vmax.', question: 'What do the intercepts of a Lineweaver-Burk plot represent?', answer: 'X-intercept = -1/Km; y-intercept = 1/Vmax.' },
  { id: 'enz-4', topicId: 'enzymes', fact: 'A low Km means high enzyme affinity for substrate (saturates at low [S]); a high Km means low affinity.', question: 'What does a low Km indicate about enzyme-substrate affinity?', answer: 'High affinity — the enzyme reaches half-maximal velocity at a low substrate concentration.' },
  { id: 'enz-5', topicId: 'enzymes', fact: 'Elevated AST/ALT with ALT > AST suggests viral hepatitis; AST > ALT (ratio >2) is classic for alcoholic liver disease.', question: 'Which liver enzyme pattern (AST vs ALT) suggests alcoholic liver disease?', answer: 'AST > ALT (ratio typically >2:1).' },
  { id: 'enz-6', topicId: 'enzymes', fact: 'Creatine kinase-MB (CK-MB) and troponin I/T rise after myocardial infarction; troponin rises later but stays elevated for 7–10 days, making it useful for late diagnosis.', question: 'Which cardiac marker stays elevated longest after an MI, and for how long?', answer: 'Troponin I/T — elevated for about 7 to 10 days.' },
  { id: 'enz-7', topicId: 'enzymes', fact: 'Alkaline phosphatase is elevated in cholestasis/biliary obstruction and in bone disease (e.g. Paget disease); GGT helps confirm a hepatobiliary source since it is not elevated in bone disease.', question: 'How do you confirm elevated ALP is from liver rather than bone?', answer: 'Check GGT — elevated in hepatobiliary disease but not in bone disease.' },
  { id: 'enz-8', topicId: 'enzymes', fact: 'Zero-order kinetics means reaction rate is constant, independent of substrate concentration, because the enzyme is fully saturated (occurs at [S] >> Km); first-order kinetics means rate is proportional to [S] (at [S] << Km).', question: 'At what substrate condition does an enzyme show zero-order kinetics?', answer: 'When [S] is far above Km — the enzyme is saturated, so rate is constant regardless of further substrate increase.' },
  { id: 'enz-9', topicId: 'enzymes', fact: 'Allosteric enzymes show a sigmoidal (S-shaped) velocity-vs-substrate curve rather than the hyperbolic Michaelis-Menten curve, reflecting cooperative binding between multiple subunits — analogous to hemoglobin\'s oxygen binding curve.', question: 'What shape does the velocity-vs-substrate curve take for an allosteric enzyme, and why?', answer: 'Sigmoidal, due to cooperative binding among multiple subunits — same principle as hemoglobin-oxygen binding.' },
  { id: 'enz-10', topicId: 'enzymes', fact: 'Covalent modification (e.g. phosphorylation by kinases, dephosphorylation by phosphatases) provides fast, reversible enzyme regulation — e.g. glycogen phosphorylase is activated by phosphorylation, glycogen synthase is inhibited by phosphorylation.', question: 'How does phosphorylation affect glycogen phosphorylase versus glycogen synthase?', answer: 'Phosphorylation activates glycogen phosphorylase but inhibits glycogen synthase — opposite effects that ensure only one pathway runs at a time.' },

  // ---- Inborn Errors of Metabolism ----
  { id: 'iem-1', topicId: 'iem', fact: 'Tay-Sachs disease (hexosaminidase A deficiency) causes GM2 ganglioside accumulation, presenting with a cherry-red macula and no hepatosplenomegaly — distinguishing it from Niemann-Pick disease.', question: 'What distinguishes Tay-Sachs from Niemann-Pick disease clinically, despite both showing a cherry-red macula?', answer: 'Tay-Sachs has no hepatosplenomegaly; Niemann-Pick does (due to sphingomyelinase deficiency and sphingomyelin accumulation in the liver/spleen).' },
  { id: 'iem-2', topicId: 'iem', fact: 'Gaucher disease, the most common lysosomal storage disease, is caused by glucocerebrosidase deficiency, causing hepatosplenomegaly and characteristic "crumpled tissue paper" macrophages.', question: 'What is the most common lysosomal storage disease, and its enzyme defect?', answer: 'Gaucher disease — glucocerebrosidase deficiency.' },
  { id: 'iem-3', topicId: 'iem', fact: 'Fabry disease (X-linked, alpha-galactosidase A deficiency) causes angiokeratomas, peripheral neuropathy, and progressive renal failure.', question: 'Which lysosomal storage disease is X-linked and causes angiokeratomas?', answer: 'Fabry disease (alpha-galactosidase A deficiency).' },
  { id: 'iem-4', topicId: 'iem', fact: 'Hurler syndrome (alpha-L-iduronidase deficiency, a mucopolysaccharidosis) causes corneal clouding, coarse facial features, and developmental delay; Hunter syndrome (iduronate sulfatase, X-linked) is similar but without corneal clouding.', question: 'What key clinical feature distinguishes Hurler from Hunter syndrome?', answer: 'Hurler has corneal clouding; Hunter (X-linked) does not.' },
  { id: 'iem-5', topicId: 'iem', fact: 'Galactosemia (classic form) is due to galactose-1-phosphate uridyltransferase deficiency, causing failure to thrive, jaundice, cataracts, and hepatomegaly if the infant is not switched off lactose-containing formula.', question: 'Which enzyme deficiency causes classic galactosemia?', answer: 'Galactose-1-phosphate uridyltransferase.' },
  { id: 'iem-6', topicId: 'iem', fact: 'Essential fructosuria (benign, fructokinase deficiency) must be distinguished from hereditary fructose intolerance (aldolase B deficiency), which is dangerous — causes hypoglycemia and liver failure on fructose/sucrose ingestion.', question: 'Which fructose metabolism disorder is dangerous, and why?', answer: 'Hereditary fructose intolerance (aldolase B deficiency) — fructose-1-phosphate accumulates, trapping phosphate and causing severe hypoglycemia and liver damage.' },
  { id: 'iem-7', topicId: 'iem', fact: "Lesch-Nyhan syndrome (X-linked HGPRT deficiency) impairs purine salvage, causing hyperuricemia, gout, self-mutilating behavior, and intellectual disability.", question: 'What enzyme is deficient in Lesch-Nyhan syndrome?', answer: 'Hypoxanthine-guanine phosphoribosyltransferase (HGPRT).' },
  { id: 'iem-8', topicId: 'iem', fact: 'Von Gierke, Pompe, Cori, and McArdle diseases are the classic glycogen storage diseases tested — remember Von Gierke = liver/hypoglycemia, Pompe = heart, McArdle = muscle/exercise intolerance without lactate rise.', question: 'Which glycogen storage disease causes exercise intolerance with no rise in lactate?', answer: "McArdle disease (myophosphorylase deficiency) — muscle can't break down glycogen for anaerobic glycolysis during exercise." },
  { id: 'iem-9', topicId: 'iem', fact: 'Orotic aciduria (UMP synthase deficiency) causes megaloblastic anemia unresponsive to B12/folate, with orotic acid crystals in urine and normal ammonia — distinguishing it from OTC deficiency, which also raises orotic acid but with hyperammonemia.', question: 'How do you distinguish orotic aciduria (UMP synthase deficiency) from OTC deficiency, since both raise orotic acid?', answer: 'Orotic aciduria has normal ammonia and megaloblastic anemia; OTC deficiency has hyperammonemia. Both share elevated orotic acid.' },
  { id: 'iem-10', topicId: 'iem', fact: 'Zellweger syndrome is a peroxisomal biogenesis disorder causing accumulation of very-long-chain fatty acids, with hypotonia, seizures, and hepatomegaly in infancy — usually fatal in the first year.', question: 'What kind of organelle defect causes Zellweger syndrome?', answer: 'Peroxisome biogenesis defect — very-long-chain fatty acids cannot be broken down (peroxisomal beta-oxidation fails).' },
  { id: 'iem-11', topicId: 'iem', fact: 'Refsum disease, a peroxisomal disorder of phytanic acid alpha-oxidation, causes night blindness, peripheral neuropathy, and cerebellar ataxia; dietary avoidance of chlorophyll-containing foods reduces phytanic acid intake.', question: 'Which fatty acid accumulates in Refsum disease?', answer: 'Phytanic acid (peroxisomal alpha-oxidation defect).' },
  { id: 'iem-12', topicId: 'iem', fact: 'Systemic primary carnitine deficiency impairs fatty acid entry into mitochondria, causing hypoketotic hypoglycemia and cardiomyopathy during fasting — carnitine transports long-chain fatty acids across the inner mitochondrial membrane as part of the CPT shuttle.', question: 'Why does carnitine deficiency cause hypoketotic hypoglycemia during fasting?', answer: 'Long-chain fatty acids cannot enter mitochondria for beta-oxidation without carnitine, so neither ATP nor ketone bodies can be generated from fat, forcing continued glucose use with no compensatory ketosis.' },

  // ---- Molecular Biology Basics ----
  { id: 'mb-1', topicId: 'molbio', fact: 'DNA polymerase III is the main replicative enzyme in bacteria, synthesizing 5\' to 3\' and proofreading via 3\' to 5\' exonuclease activity; DNA polymerase I removes RNA primers and fills gaps using its 5\' to 3\' exonuclease activity.', question: 'What is the proofreading direction of DNA polymerase exonuclease activity during synthesis?', answer: "3' to 5' exonuclease activity proofreads (removes mismatched nucleotides); synthesis itself always proceeds 5' to 3'." },
  { id: 'mb-2', topicId: 'molbio', fact: 'Topoisomerase II (DNA gyrase in bacteria) relieves supercoiling ahead of the replication fork by cutting both DNA strands; fluoroquinolone antibiotics target bacterial DNA gyrase.', question: 'Which class of antibiotics inhibits DNA gyrase?', answer: 'Fluoroquinolones (e.g. ciprofloxacin).' },
  { id: 'mb-3', topicId: 'molbio', fact: 'The lagging strand is synthesized discontinuously as Okazaki fragments, joined by DNA ligase after RNA primers are removed — this is why lagging-strand synthesis is slower and needs more enzymatic steps than the leading strand.', question: 'Which enzyme joins Okazaki fragments together?', answer: 'DNA ligase.' },
  { id: 'mb-4', topicId: 'molbio', fact: 'Nucleotide excision repair fixes bulky helix-distorting lesions (e.g. UV-induced thymine dimers); defects cause xeroderma pigmentosum, with severe photosensitivity and skin cancer risk.', question: 'Which DNA repair defect causes xeroderma pigmentosum?', answer: 'Nucleotide excision repair defect — cannot repair UV-induced pyrimidine (thymine) dimers.' },
  { id: 'mb-5', topicId: 'molbio', fact: 'Mismatch repair corrects base-pairing errors missed by proofreading after replication; defects cause hereditary nonpolyposis colorectal cancer (Lynch syndrome).', question: 'Which repair pathway is defective in Lynch syndrome (HNPCC)?', answer: 'Mismatch repair.' },
  { id: 'mb-6', topicId: 'molbio', fact: 'RNA polymerase II transcribes mRNA (and is inhibited by alpha-amanitin from death cap mushrooms); RNA polymerase I makes rRNA, RNA polymerase III makes tRNA and 5S rRNA.', question: 'Which RNA polymerase does alpha-amanitin (death cap mushroom toxin) inhibit?', answer: 'RNA polymerase II — causes fatal hepatotoxicity by blocking mRNA synthesis.' },
  { id: 'mb-7', topicId: 'molbio', fact: 'The start codon AUG codes for methionine (formylmethionine in bacteria); stop codons UAA, UAG, and UGA (remembered as "U Are Annoying, U Are Gone, U Go Away") do not code for any amino acid.', question: 'What are the three stop codons?', answer: 'UAA, UAG, UGA.' },
  { id: 'mb-8', topicId: 'molbio', fact: 'Aminoglycosides (e.g. gentamicin) cause misreading of mRNA at the 30S ribosomal subunit; macrolides and chloramphenicol block the 50S subunit — a classic exam distinction of bacterial protein synthesis inhibitors by ribosomal subunit.', question: 'Which ribosomal subunit do aminoglycosides act on, versus macrolides?', answer: 'Aminoglycosides act on the 30S subunit; macrolides (and chloramphenicol, clindamycin) act on the 50S subunit.' },

  // ---- Hemoglobin & Porphyrin Metabolism ----
  { id: 'heme-1', topicId: 'heme', fact: 'ALA synthase (delta-aminolevulinate synthase), the rate-limiting enzyme of heme synthesis, requires vitamin B6 (pyridoxal phosphate) and is inhibited by heme itself (negative feedback).', question: 'What is the rate-limiting enzyme of heme synthesis, and its cofactor?', answer: 'ALA synthase — requires vitamin B6 (pyridoxal phosphate), feedback-inhibited by heme.' },
  { id: 'heme-2', topicId: 'heme', fact: 'Lead poisoning inhibits ALA dehydratase and ferrochelatase in heme synthesis, causing microcytic anemia with basophilic stippling and elevated blood lead levels.', question: 'Which two heme synthesis enzymes does lead inhibit?', answer: 'ALA dehydratase and ferrochelatase.' },
  { id: 'heme-3', topicId: 'heme', fact: 'Acute intermittent porphyria (porphobilinogen deaminase deficiency) presents with the classic triad of abdominal pain, neuropsychiatric symptoms, and port-wine colored urine, often triggered by drugs that induce ALA synthase (e.g. barbiturates).', question: 'What triggers acute intermittent porphyria attacks?', answer: 'Drugs/factors that induce ALA synthase — classically barbiturates, alcohol, and starvation.' },
  { id: 'heme-4', topicId: 'heme', fact: 'Porphyria cutanea tarda (uroporphyrinogen decarboxylase deficiency), the most common porphyria, causes painful photosensitivity and blistering of sun-exposed skin, and is associated with hepatitis C and alcohol use.', question: 'What is the most common porphyria, and its key clinical feature?', answer: 'Porphyria cutanea tarda — photosensitive blistering skin lesions, associated with hepatitis C/alcohol.' },
  { id: 'heme-5', topicId: 'heme', fact: 'Unconjugated (indirect) bilirubin is lipid-soluble and albumin-bound in blood; the liver conjugates it with glucuronic acid via UDP-glucuronosyltransferase to make it water-soluble for biliary excretion.', question: 'Which enzyme conjugates bilirubin in the liver?', answer: 'UDP-glucuronosyltransferase (UGT1A1).' },
  { id: 'heme-6', topicId: 'heme', fact: 'Crigler-Najjar syndrome type I (complete UGT1A1 deficiency) causes severe unconjugated hyperbilirubinemia and kernicterus risk; Gilbert syndrome (mild UGT1A1 reduction) causes benign, mild unconjugated hyperbilirubinemia often triggered by stress or fasting.', question: 'How does Gilbert syndrome differ from Crigler-Najjar type I?', answer: 'Both reduce UGT1A1 activity, but Gilbert is a mild, benign reduction; Crigler-Najjar type I is a complete, severe deficiency risking kernicterus.' },
  { id: 'heme-7', topicId: 'heme', fact: 'Physiologic neonatal jaundice results from immature UGT1A1 activity combined with high fetal hemoglobin turnover, causing transient unconjugated hyperbilirubinemia in the first days of life.', question: 'Why do healthy newborns commonly develop jaundice?', answer: 'Immature UDP-glucuronosyltransferase activity plus high turnover of fetal red blood cells, causing transient unconjugated hyperbilirubinemia.' },

  // ---- Water, Electrolyte & Acid-Base Biochemistry ----
  { id: 'wea-1', topicId: 'water-electrolyte', fact: 'The Henderson-Hasselbalch equation, pH = pKa + log([A-]/[HA]), describes how buffer pairs resist pH change and underlies the bicarbonate buffer system: pH = 6.1 + log([HCO3-]/[0.03 x PaCO2]).', question: 'What is the Henderson-Hasselbalch equation for the bicarbonate buffer system?', answer: 'pH = 6.1 + log([HCO3-] / (0.03 × PaCO2]).' },
  { id: 'wea-2', topicId: 'water-electrolyte', fact: 'A buffer resists pH change most effectively when pH is within 1 unit of its pKa; the bicarbonate system works physiologically because the lungs and kidneys continuously regenerate its components, not because its pKa (6.1) is close to blood pH (7.4).', question: 'Why is the bicarbonate buffer effective in blood despite its pKa (6.1) being far from blood pH (7.4)?', answer: "Because it's an open system — the lungs (CO2) and kidneys (HCO3-) continuously regulate both components, rather than relying on the pKa alone." },
  { id: 'wea-3', topicId: 'water-electrolyte', fact: 'Hemoglobin acts as a major intracellular buffer via histidine residues; deoxygenated hemoglobin binds H+ more readily than oxygenated hemoglobin (the Bohr effect facilitates CO2/H+ transport from tissues).', question: 'Why does deoxyhemoglobin buffer H+ better than oxyhemoglobin?', answer: 'Deoxyhemoglobin has a higher affinity for H+ via histidine residues — part of the Bohr effect, which helps unload O2 in acidic, CO2-rich tissues.' },
  { id: 'wea-4', topicId: 'water-electrolyte', fact: 'The phosphate buffer system (H2PO4-/HPO4^2-, pKa ~6.8) is a more effective intracellular and urinary buffer than plasma buffer, since its pKa lies closer to intracellular pH.', question: 'Which buffer system is most effective intracellularly, and why?', answer: 'The phosphate buffer system — its pKa (~6.8) is close to intracellular pH.' },
  { id: 'wea-5', topicId: 'water-electrolyte', fact: 'The anion gap = Na+ - (Cl- + HCO3-); a high anion gap metabolic acidosis suggests unmeasured acids (e.g. ketoacids, lactate, toxins), while a normal anion gap acidosis suggests bicarbonate loss (e.g. diarrhea, renal tubular acidosis).', question: 'What does a high anion gap metabolic acidosis suggest, versus a normal anion gap acidosis?', answer: 'High anion gap: unmeasured acids present (ketoacidosis, lactic acidosis, toxins). Normal anion gap: bicarbonate loss (diarrhea, renal tubular acidosis) with compensatory chloride rise.' },

  // ---- Endocrine Biochemistry ----
  { id: 'endo-1', topicId: 'endocrine', fact: 'Peptide hormones (e.g. insulin, glucagon) are water-soluble and act via cell-surface receptors and second messengers, since they cannot cross the lipid bilayer; steroid/thyroid hormones are lipid-soluble and act via intracellular/nuclear receptors that directly alter gene transcription.', question: 'Why do peptide hormones need second messengers but steroid hormones do not?', answer: "Peptide hormones are water-soluble and can't cross the plasma membrane, so they signal via surface receptors and second messengers. Steroid/thyroid hormones are lipid-soluble and diffuse in to bind intracellular receptors directly." },
  { id: 'endo-2', topicId: 'endocrine', fact: 'Gs-protein-coupled receptors activate adenylate cyclase, raising cAMP (e.g. glucagon, ACTH, TSH, LH, FSH — remembered by many as the "FLAT ChAMP" receptors); Gq-coupled receptors activate phospholipase C, raising IP3 and DAG (e.g. GnRH, TRH, oxytocin).', question: 'What second messenger do Gs-coupled hormone receptors raise, versus Gq-coupled receptors?', answer: 'Gs raises cAMP; Gq raises IP3/DAG (via phospholipase C).' },
  { id: 'endo-3', topicId: 'endocrine', fact: 'Insulin signals through a receptor tyrosine kinase, autophosphorylating and activating downstream pathways (e.g. via IRS proteins) rather than using cAMP or IP3 as its primary second messenger.', question: "What kind of receptor does insulin use?", answer: 'A receptor tyrosine kinase.' },
  { id: 'endo-4', topicId: 'endocrine', fact: 'Cortisol, a glucocorticoid, raises blood glucose by promoting gluconeogenesis and insulin resistance, mobilizes fatty acids, and suppresses the immune system — synthesized from cholesterol in the adrenal cortex.', question: 'What are the main metabolic effects of cortisol?', answer: 'Increases gluconeogenesis and blood glucose, promotes lipolysis, and suppresses immune/inflammatory responses.' },
  { id: 'endo-5', topicId: 'endocrine', fact: 'Thyroid hormone synthesis requires thyroid peroxidase to oxidize iodide and couple iodotyrosines into T3/T4; propylthiouracil and methimazole treat hyperthyroidism by inhibiting this enzyme.', question: 'Which enzyme do antithyroid drugs like methimazole inhibit?', answer: 'Thyroid peroxidase.' },
  { id: 'endo-6', topicId: 'endocrine', fact: 'Catecholamines (epinephrine, norepinephrine) are synthesized from tyrosine via tyrosine hydroxylase (the rate-limiting step) through L-DOPA and dopamine; this is the same precursor amino acid that feeds melanin synthesis via a separate pathway.', question: 'What is the rate-limiting enzyme of catecholamine synthesis?', answer: 'Tyrosine hydroxylase.' },

  // ---- Chemistry of Carbohydrates ----
  { id: 'cc-1', topicId: 'chem-carb', fact: 'Monosaccharides are classified as aldoses or ketoses by their carbonyl group, and by carbon number (triose, tetrose, pentose, hexose).', question: 'How are monosaccharides classified?', answer: 'By carbonyl type (aldose vs ketose) and carbon chain length (triose to heptose).' },
  { id: 'cc-2', topicId: 'chem-carb', fact: 'Glucose and galactose are epimers differing only in configuration at C4; glucose and mannose are epimers differing at C2.', question: 'What is an epimer? Give an example pair.', answer: 'Sugars differing in configuration at only one chiral carbon — e.g. glucose/galactose differ at C4.' },
  { id: 'cc-3', topicId: 'chem-carb', fact: 'Reducing sugars (glucose, fructose, lactose, maltose) have a free anomeric hydroxyl and give a positive Benedict\'s test; sucrose is non-reducing because both anomeric carbons form the glycosidic bond.', question: 'Why is sucrose a non-reducing sugar?', answer: 'Both anomeric carbons (of glucose and fructose) are locked into the glycosidic bond, leaving no free anomeric OH.' },
  { id: 'cc-4', topicId: 'chem-carb', fact: 'Lactose intolerance results from lactase deficiency; undigested lactose is fermented by colonic bacteria, causing osmotic diarrhea, bloating, and gas.', question: 'What causes lactose intolerance?', answer: 'Lactase deficiency — undigested lactose ferments in the colon, causing osmotic diarrhea and gas.' },
  { id: 'cc-5', topicId: 'chem-carb', fact: 'Starch contains amylose (unbranched, α-1,4 links) and amylopectin (α-1,4 with α-1,6 branches); glycogen is even more branched than amylopectin, branching roughly every 8-10 residues.', question: 'How does glycogen differ structurally from amylopectin?', answer: 'Glycogen is more heavily branched (every 8-10 residues vs 24-30 in amylopectin).' },
  { id: 'cc-6', topicId: 'chem-carb', fact: 'Mutarotation is the change in optical rotation as α and β anomers interconvert in solution through the open-chain aldehyde/ketone form.', question: 'What is mutarotation?', answer: 'The spontaneous interconversion of α and β anomers via the open-chain form, changing optical rotation.' },
  { id: 'cc-7', topicId: 'chem-carb', fact: 'Essential fructosuria (fructokinase deficiency) is a benign, asymptomatic condition, unlike hereditary fructose intolerance (aldolase B deficiency), which causes severe hypoglycemia and liver damage after fructose ingestion.', question: 'How does essential fructosuria differ from hereditary fructose intolerance?', answer: 'Essential fructosuria (fructokinase deficiency) is benign; hereditary fructose intolerance (aldolase B deficiency) causes hypoglycemia and liver damage.' },
  { id: 'cc-8', topicId: 'chem-carb', fact: 'Classic galactosemia is caused by galactose-1-phosphate uridyltransferase (GALT) deficiency, presenting with cataracts, hepatomegaly, and intellectual disability if untreated.', question: 'Which enzyme deficiency causes classic galactosemia?', answer: 'Galactose-1-phosphate uridyltransferase (GALT).' },

  // ---- Chemistry of Proteins & Amino Acids ----
  { id: 'cp-1', topicId: 'chem-protein', fact: 'All standard amino acids except glycine are chiral and exist as the L-isomer in human proteins; glycine has no chiral center since its side chain is a hydrogen atom.', question: 'Why is glycine not chiral?', answer: 'Its side chain is a hydrogen atom, so it has no four distinct substituents on the alpha carbon.' },
  { id: 'cp-2', topicId: 'chem-protein', fact: 'The isoelectric point (pI) of an amino acid is the pH at which it carries no net charge; at this pH the amino acid will not migrate in an electric field.', question: 'What is the isoelectric point (pI)?', answer: 'The pH at which an amino acid/protein carries zero net charge and does not migrate in electrophoresis.' },
  { id: 'cp-3', topicId: 'chem-protein', fact: 'Primary structure is the amino acid sequence; secondary structure (alpha helix, beta sheet) is stabilized by hydrogen bonds between backbone atoms; tertiary structure is the 3D fold stabilized by side-chain interactions including disulfide bonds.', question: 'What stabilizes secondary structure?', answer: 'Hydrogen bonds between backbone carbonyl and amide groups.' },
  { id: 'cp-4', topicId: 'chem-protein', fact: 'The biuret test detects the peptide bond itself (positive for any protein/peptide with 2+ peptide bonds), while the ninhydrin test detects free alpha-amino groups, useful for quantifying free amino acids.', question: 'What does the biuret test detect versus the ninhydrin test?', answer: 'Biuret detects peptide bonds (protein presence); ninhydrin detects free alpha-amino groups.' },
  { id: 'cp-5', topicId: 'chem-protein', fact: 'Denaturation disrupts secondary, tertiary, and quaternary structure (via heat, extreme pH, or agents like urea) without breaking peptide bonds, so primary structure is preserved.', question: 'What happens to a protein\'s primary structure during denaturation?', answer: 'It is preserved — only secondary/tertiary/quaternary structure is disrupted, not peptide bonds.' },
  { id: 'cp-6', topicId: 'chem-protein', fact: 'Collagen is unusually rich in glycine (every third residue), proline, and hydroxyproline; hydroxylation of proline and lysine requires vitamin C, explaining the connective tissue defects of scurvy.', question: 'Why does vitamin C deficiency (scurvy) weaken connective tissue?', answer: 'Vitamin C is a cofactor for prolyl/lysyl hydroxylase, needed to stabilize the collagen triple helix.' },
  { id: 'cp-7', topicId: 'chem-protein', fact: 'Sickle cell disease results from a single point mutation (Glu6Val) on the beta-globin chain, replacing a polar glutamate with a hydrophobic valine, promoting HbS polymerization under low oxygen.', question: 'What mutation causes sickle cell disease?', answer: 'A Glu-to-Val substitution at position 6 of the beta-globin chain (HbS).' },
  { id: 'cp-8', topicId: 'chem-protein', fact: 'Essential amino acids (e.g. leucine, lysine, methionine, phenylalanine, threonine, tryptophan, valine, isoleucine, histidine) cannot be synthesized by the body and must come from the diet.', question: 'Name a mnemonic category for amino acids that must be obtained from the diet.', answer: 'Essential amino acids — e.g. PVT TIM HALL (phenylalanine, valine, tryptophan, threonine, isoleucine, methionine, histidine, arginine, leucine, lysine).' },

  // ---- Plasma Proteins & Immunoglobulins ----
  { id: 'pp-1', topicId: 'plasma-proteins', fact: 'Albumin, synthesized by the liver, is the most abundant plasma protein and the major contributor to plasma oncotic (colloid osmotic) pressure.', question: 'What is the main function of albumin in plasma?', answer: 'Maintaining plasma oncotic pressure (it is also a carrier for bilirubin, drugs, and fatty acids).' },
  { id: 'pp-2', topicId: 'plasma-proteins', fact: 'Serum protein electrophoresis separates plasma proteins into albumin, alpha-1, alpha-2, beta, and gamma globulin bands; the gamma band is mainly immunoglobulins.', question: 'What does the gamma globulin band on serum electrophoresis represent?', answer: 'Mainly immunoglobulins (antibodies).' },
  { id: 'pp-3', topicId: 'plasma-proteins', fact: 'Alpha-1 antitrypsin deficiency causes early-onset emphysema (unopposed neutrophil elastase activity) and can cause liver cirrhosis from accumulation of misfolded protein in hepatocytes.', question: 'What two organs are affected by alpha-1 antitrypsin deficiency, and why?', answer: 'Lungs (emphysema from unchecked elastase) and liver (cirrhosis from misfolded protein accumulation).' },
  { id: 'pp-4', topicId: 'plasma-proteins', fact: 'C-reactive protein (CRP) and ferritin are positive acute-phase reactants that rise in inflammation, while albumin and transferrin are negative acute-phase reactants that fall.', question: 'Is CRP a positive or negative acute-phase reactant?', answer: 'Positive — it rises during acute inflammation.' },
  { id: 'pp-5', topicId: 'plasma-proteins', fact: 'IgG is the only immunoglobulin that crosses the placenta, providing passive immunity to the fetus/newborn; IgM is the first antibody produced in a primary immune response.', question: 'Which immunoglobulin crosses the placenta?', answer: 'IgG.' },
  { id: 'pp-6', topicId: 'plasma-proteins', fact: 'IgA is the predominant immunoglobulin in secretions (saliva, tears, breast milk, mucosa), typically as a secretory dimer, protecting mucosal surfaces.', question: 'Which immunoglobulin dominates in mucosal secretions?', answer: 'IgA (as secretory IgA, a dimer).' },
  { id: 'pp-7', topicId: 'plasma-proteins', fact: 'Immunoglobulin structure consists of two heavy and two light chains linked by disulfide bonds, with variable regions forming the antigen-binding (Fab) site and a constant Fc region mediating effector function.', question: 'Which part of an antibody binds antigen?', answer: 'The variable regions of the Fab fragment.' },
  { id: 'pp-8', topicId: 'plasma-proteins', fact: 'Multiple myeloma produces a monoclonal immunoglobulin spike (M-spike) on electrophoresis, and light chains (Bence Jones proteins) may appear in urine.', question: 'What finding on serum electrophoresis suggests multiple myeloma?', answer: 'A monoclonal spike (M-spike), usually in the gamma region.' },

  // ---- Nucleic Acid Chemistry ----
  { id: 'na-1', topicId: 'nucleic-acid', fact: 'A nucleotide consists of a nitrogenous base, a pentose sugar (ribose in RNA, deoxyribose in DNA), and one or more phosphate groups.', question: 'What are the three components of a nucleotide?', answer: 'A nitrogenous base, a pentose sugar, and phosphate group(s).' },
  { id: 'na-2', topicId: 'nucleic-acid', fact: 'Purines (adenine, guanine) have a double-ring structure; pyrimidines (cytosine, thymine, uracil) have a single ring. DNA uses thymine, RNA uses uracil in place of thymine.', question: 'What structurally distinguishes purines from pyrimidines?', answer: 'Purines have a fused double-ring structure; pyrimidines have a single ring.' },
  { id: 'na-3', topicId: 'nucleic-acid', fact: "Chargaff's rules state that in double-stranded DNA, the amount of adenine equals thymine and guanine equals cytosine, reflecting complementary base pairing.", question: "What do Chargaff's rules state?", answer: 'A = T and G = C in double-stranded DNA (reflecting Watson-Crick base pairing).' },
  { id: 'na-4', topicId: 'nucleic-acid', fact: 'DNA is a right-handed double helix (B-form) with antiparallel strands held together by hydrogen bonds — 2 between A-T and 3 between G-C, making G-C pairs more thermally stable.', question: 'Why are G-C rich DNA regions more thermally stable than A-T rich regions?', answer: 'G-C pairs form 3 hydrogen bonds versus 2 for A-T pairs.' },
  { id: 'na-5', topicId: 'nucleic-acid', fact: 'RNA is typically single-stranded and can fold into secondary structures (hairpins, stem-loops); the three major types are mRNA, tRNA, and rRNA, each with distinct roles in protein synthesis.', question: 'What are the three major types of RNA involved in translation?', answer: 'mRNA (carries the code), tRNA (delivers amino acids), rRNA (structural/catalytic component of ribosomes).' },
  { id: 'na-6', topicId: 'nucleic-acid', fact: 'Nucleic acids absorb UV light maximally at 260 nm; the A260/A280 ratio is used to assess DNA purity, with ~1.8 indicating relatively pure DNA (protein contamination lowers this ratio).', question: 'At what wavelength do nucleic acids show maximal UV absorbance?', answer: '260 nm.' },
  { id: 'na-7', topicId: 'nucleic-acid', fact: 'Purine catabolism produces uric acid in humans; hyperuricemia can cause gout, and Lesch-Nyhan syndrome results from HGPRT deficiency, impairing purine salvage and causing uric acid overproduction.', question: 'Which enzyme deficiency causes Lesch-Nyhan syndrome?', answer: 'Hypoxanthine-guanine phosphoribosyltransferase (HGPRT) deficiency.' },
  { id: 'na-8', topicId: 'nucleic-acid', fact: 'Pyrimidine synthesis is regulated by carbamoyl phosphate synthetase II (CPS II) in the cytosol, distinct from the mitochondrial CPS I of the urea cycle; orotic aciduria results from a block in this pathway.', question: 'Which enzyme distinguishes cytosolic pyrimidine synthesis from the urea cycle\'s carbamoyl phosphate step?', answer: 'Carbamoyl phosphate synthetase II (cytosolic, pyrimidine synthesis) vs CPS I (mitochondrial, urea cycle).' },

  // ---- Extracellular Matrix ----
  { id: 'ecm-1', topicId: 'ecm', fact: 'Collagen is the most abundant protein in the body; type I predominates in bone, skin, and tendon, type II in cartilage, and type III in blood vessels and healing wounds.', question: 'Which collagen type predominates in cartilage?', answer: 'Type II collagen.' },
  { id: 'ecm-2', topicId: 'ecm', fact: 'Collagen synthesis requires hydroxylation of proline and lysine residues (vitamin C-dependent), glycosylation, triple helix formation, and extracellular cross-linking by lysyl oxidase (a copper-dependent enzyme).', question: 'Which trace element is required for lysyl oxidase, the enzyme that cross-links collagen?', answer: 'Copper.' },
  { id: 'ecm-3', topicId: 'ecm', fact: 'Ehlers-Danlos syndrome results from defective collagen synthesis or structure, causing hyperelastic skin and joint hypermobility; Marfan syndrome results from a fibrillin-1 defect, not collagen.', question: 'Is Marfan syndrome a collagen disorder?', answer: 'No — it is caused by a defect in fibrillin-1, an elastic fiber protein.' },
  { id: 'ecm-4', topicId: 'ecm', fact: 'Elastin provides reversible stretch to tissues (lungs, large arteries, ligaments) and is cross-linked via desmosine bonds; its precursor tropoelastin lacks hydroxyproline/hydroxylysine, unlike collagen.', question: 'What structural feature gives elastin its recoil properties?', answer: 'Cross-linking via desmosine bonds between lysine residues, forming an elastic network.' },
  { id: 'ecm-5', topicId: 'ecm', fact: 'Glycosaminoglycans (GAGs) like hyaluronic acid, chondroitin sulfate, and heparan sulfate are long, negatively charged polysaccharides that bind water, providing cartilage and joint fluid with compressive resistance.', question: 'Why do glycosaminoglycans give cartilage its compressive strength?', answer: 'Their negative charge attracts water, creating swelling pressure that resists compression.' },
  { id: 'ecm-6', topicId: 'ecm', fact: 'Proteoglycans consist of a core protein with covalently attached GAG chains; aggrecan is the major proteoglycan of cartilage, aggregating with hyaluronic acid via link proteins.', question: 'What is the major proteoglycan of cartilage?', answer: 'Aggrecan.' },
  { id: 'ecm-7', topicId: 'ecm', fact: 'Heparin, an intracellular/mast-cell GAG (not present in normal blood), is used clinically as an anticoagulant because it activates antithrombin III.', question: 'How does heparin act as an anticoagulant?', answer: 'It binds and activates antithrombin III, which inhibits thrombin and factor Xa.' },
  { id: 'ecm-8', topicId: 'ecm', fact: 'Fibronectin is a large glycoprotein that mediates cell adhesion to the extracellular matrix by binding both integrins on the cell surface and matrix components like collagen.', question: 'What is the main function of fibronectin?', answer: 'Mediating cell-to-matrix adhesion by bridging integrins and matrix components (e.g. collagen).' },

  // ---- Nutrition ----
  { id: 'nu-1', topicId: 'nutrition', fact: 'Basal metabolic rate (BMR) is the energy expended at complete rest, accounting for the largest share of total daily energy expenditure in most sedentary individuals.', question: 'What does BMR represent?', answer: 'The minimum energy required to maintain basic physiological functions at rest.' },
  { id: 'nu-2', topicId: 'nutrition', fact: 'Kwashiorkor results from adequate calorie but severe protein deficiency, causing edema, a fatty liver, and hypoalbuminemia; marasmus results from overall calorie-protein deficiency, causing severe wasting without edema.', question: 'How does kwashiorkor differ from marasmus?', answer: 'Kwashiorkor: protein deficiency with edema and fatty liver despite adequate calories. Marasmus: total calorie-protein deficiency with severe wasting, no edema.' },
  { id: 'nu-3', topicId: 'nutrition', fact: 'Protein quality is measured by biological value and the presence of essential amino acids; egg protein has one of the highest biological values and is used as a reference standard.', question: 'What is biological value a measure of?', answer: 'How efficiently a dietary protein is converted into body protein, considering its essential amino acid content.' },
  { id: 'nu-4', topicId: 'nutrition', fact: 'Dietary fiber (cellulose, pectin) is not digested by human enzymes but is fermented by colonic bacteria and aids bowel regularity; soluble fiber also slows glucose absorption and lowers cholesterol.', question: 'How does soluble dietary fiber affect blood glucose and cholesterol?', answer: 'It slows glucose absorption and lowers cholesterol by binding bile acids.' },
  { id: 'nu-5', topicId: 'nutrition', fact: 'Respiratory quotient (RQ) is the ratio of CO2 produced to O2 consumed; carbohydrate oxidation gives an RQ of 1.0, fat oxidation about 0.7, and mixed diet roughly 0.8.', question: 'What is the respiratory quotient for pure carbohydrate oxidation?', answer: '1.0.' },
  { id: 'nu-6', topicId: 'nutrition', fact: 'Obesity is commonly assessed using body mass index (BMI = weight in kg / height in m²), with a BMI of 25-29.9 classified as overweight and ≥30 as obese by WHO criteria.', question: 'What BMI range is classified as obese by WHO criteria?', answer: 'BMI ≥ 30 kg/m².' },
  { id: 'nu-7', topicId: 'nutrition', fact: 'Trans fats, formed by partial hydrogenation of vegetable oils, raise LDL and lower HDL cholesterol, increasing cardiovascular risk more than saturated fats.', question: 'How do trans fats affect the lipid profile?', answer: 'They raise LDL cholesterol and lower HDL cholesterol.' },
  { id: 'nu-8', topicId: 'nutrition', fact: 'Specific dynamic action (thermic effect of food) refers to the energy expended in digesting, absorbing, and metabolizing food; it is highest for protein (~20-30%) compared to carbohydrate or fat.', question: 'Which macronutrient has the highest thermic effect (specific dynamic action)?', answer: 'Protein.' },

  // ---- Digestion & Absorption ----
  { id: 'da-1', topicId: 'digestion', fact: 'Salivary alpha-amylase begins starch digestion in the mouth, but is inactivated by gastric acid; pancreatic alpha-amylase completes starch digestion to maltose, maltotriose, and dextrins in the duodenum.', question: 'Why does starch digestion pause temporarily in the stomach?', answer: 'Gastric acid inactivates salivary amylase.' },
  { id: 'da-2', topicId: 'digestion', fact: 'Brush-border enzymes (maltase, sucrase-isomaltase, lactase) hydrolyze disaccharides into absorbable monosaccharides; lactase deficiency is the most common disaccharidase deficiency worldwide.', question: 'Where are the enzymes that complete carbohydrate digestion located?', answer: 'On the intestinal brush border (enterocyte apical membrane).' },
  { id: 'da-3', topicId: 'digestion', fact: 'Glucose and galactose are absorbed via the SGLT1 sodium-glucose cotransporter (secondary active transport), while fructose is absorbed via facilitated diffusion through GLUT5.', question: 'What transporter absorbs fructose across the intestinal brush border?', answer: 'GLUT5, via facilitated diffusion.' },
  { id: 'da-4', topicId: 'digestion', fact: 'Pepsin, activated from pepsinogen by gastric acid, begins protein digestion in the stomach; pancreatic proteases (trypsin, chymotrypsin, carboxypeptidases) complete digestion in the small intestine.', question: 'What activates pepsinogen to pepsin?', answer: 'Gastric hydrochloric acid (and autocatalytically by pepsin itself).' },
  { id: 'da-5', topicId: 'digestion', fact: 'Trypsinogen is activated to trypsin by enteropeptidase (enterokinase) on the duodenal brush border; trypsin then autoactivates more trypsinogen and other pancreatic zymogens.', question: 'Which enzyme activates trypsinogen?', answer: 'Enteropeptidase (enterokinase), located on the duodenal brush border.' },
  { id: 'da-6', topicId: 'digestion', fact: 'Dietary triglycerides are emulsified by bile salts, digested by pancreatic lipase (aided by colipase) to monoglycerides and free fatty acids, then packaged into micelles for absorption.', question: 'What role does colipase play in fat digestion?', answer: 'It anchors pancreatic lipase to the lipid-water interface, preventing bile salt inhibition of the enzyme.' },
  { id: 'da-7', topicId: 'digestion', fact: 'Absorbed long-chain fatty acids and monoglycerides are re-esterified into triglycerides in enterocytes and packaged into chylomicrons for transport via lymphatics; short/medium-chain fatty acids go directly into the portal blood.', question: 'How do long-chain fatty acids reach the bloodstream after absorption?', answer: 'Packaged into chylomicrons and transported via intestinal lymphatics before entering systemic circulation.' },
  { id: 'da-8', topicId: 'digestion', fact: 'Vitamin B12 absorption requires intrinsic factor (secreted by gastric parietal cells) to form a complex absorbed via receptor-mediated endocytosis in the terminal ileum.', question: 'Where is vitamin B12 absorbed, and what carrier protein is required?', answer: 'Terminal ileum, bound to intrinsic factor from gastric parietal cells.' },

  // ---- Organ Function Tests ----
  { id: 'oft-1', topicId: 'organ-function', fact: 'Liver function tests include serum bilirubin, AST/ALT (hepatocellular injury markers), alkaline phosphatase and GGT (cholestasis markers), and albumin/PT (synthetic function).', question: 'Which liver enzyme is most specific for hepatocyte injury versus cholestasis?', answer: 'ALT (alanine aminotransferase) is more liver-specific than AST; ALP/GGT indicate cholestasis.' },
  { id: 'oft-2', topicId: 'organ-function', fact: 'ALT is more liver-specific than AST, since AST is also present in cardiac and skeletal muscle, red blood cells, and other tissues.', question: 'Why is ALT considered more liver-specific than AST?', answer: 'AST is also found in heart, skeletal muscle, and RBCs, while ALT is predominantly hepatic.' },
  { id: 'oft-3', topicId: 'organ-function', fact: 'Glomerular filtration rate (GFR) is best estimated using serum creatinine (a muscle creatine breakdown product, freely filtered and minimally reabsorbed) rather than urea, which is affected by protein intake and hydration.', question: 'Why is creatinine preferred over urea for estimating GFR?', answer: 'Creatinine is produced at a constant rate and is not significantly affected by diet or hydration, unlike urea.' },
  { id: 'oft-4', topicId: 'organ-function', fact: 'Cardiac troponins (I and T) are the most sensitive and specific biomarkers for myocardial infarction, rising within 3-6 hours and remaining elevated for days, outperforming CK-MB.', question: 'What is the most specific biomarker for diagnosing myocardial infarction?', answer: 'Cardiac troponin I or T.' },
  { id: 'oft-5', topicId: 'organ-function', fact: 'Amylase and lipase are elevated in acute pancreatitis; lipase rises later but stays elevated longer and is more specific to the pancreas than amylase.', question: 'Which pancreatic enzyme is more specific for pancreatitis, amylase or lipase?', answer: 'Lipase — it is more specific and stays elevated longer than amylase.' },
  { id: 'oft-6', topicId: 'organ-function', fact: 'Conjugated (direct) bilirubin is water-soluble and elevated in post-hepatic (obstructive) and hepatocellular jaundice; unconjugated (indirect) bilirubin is elevated in pre-hepatic (hemolytic) jaundice.', question: 'Which form of bilirubin is elevated in hemolytic jaundice?', answer: 'Unconjugated (indirect) bilirubin.' },
  { id: 'oft-7', topicId: 'organ-function', fact: 'Prothrombin time (PT) reflects the extrinsic and common coagulation pathways and liver synthetic function (clotting factors have short half-lives), making it useful for assessing acute liver failure severity.', question: 'Why is PT a sensitive marker of acute liver failure?', answer: 'Clotting factors (synthesized by the liver) have short half-lives, so PT prolongs quickly when synthetic function fails.' },
  { id: 'oft-8', topicId: 'organ-function', fact: 'Elevated creatine kinase-MB (CK-MB) suggests cardiac muscle injury, while elevated total CK with normal CK-MB suggests skeletal muscle damage (e.g. rhabdomyolysis).', question: 'What does an elevated total CK with a normal CK-MB fraction suggest?', answer: 'Skeletal muscle injury rather than cardiac injury (e.g. rhabdomyolysis).' },

  // ---- Free Radicals, Antioxidants & Detoxification ----
  { id: 'fr-1', topicId: 'free-radicals', fact: 'Reactive oxygen species (superoxide, hydrogen peroxide, hydroxyl radical) are generated as byproducts of oxidative phosphorylation and can damage lipids, proteins, and DNA if not neutralized.', question: 'Where are most reactive oxygen species generated in the cell?', answer: 'The mitochondrial electron transport chain, as byproducts of oxidative phosphorylation.' },
  { id: 'fr-2', topicId: 'free-radicals', fact: 'Superoxide dismutase converts superoxide to hydrogen peroxide, which is then detoxified to water by catalase (peroxisomes) or glutathione peroxidase (cytosol, selenium-dependent).', question: 'Which enzyme requires selenium to detoxify hydrogen peroxide?', answer: 'Glutathione peroxidase.' },
  { id: 'fr-3', topicId: 'free-radicals', fact: 'Vitamins C and E are major dietary antioxidants — vitamin E (lipid-soluble) protects membrane lipids from peroxidation, while vitamin C (water-soluble) regenerates oxidized vitamin E and scavenges aqueous radicals.', question: 'How do vitamin C and vitamin E work together as antioxidants?', answer: 'Vitamin E neutralizes lipid radicals in membranes; vitamin C regenerates the reduced (active) form of vitamin E.' },
  { id: 'fr-4', topicId: 'free-radicals', fact: 'Xenobiotic (drug) metabolism occurs in two phases: Phase I (cytochrome P450-mediated oxidation, often producing a reactive intermediate) and Phase II (conjugation with glucuronic acid, sulfate, or glutathione to increase water solubility for excretion).', question: 'What is the difference between Phase I and Phase II drug metabolism?', answer: 'Phase I (mainly cytochrome P450) oxidizes/modifies the drug; Phase II conjugates it to increase water solubility for excretion.' },
  { id: 'fr-5', topicId: 'free-radicals', fact: 'Paracetamol (acetaminophen) overdose depletes hepatic glutathione, allowing the toxic Phase I metabolite NAPQI to accumulate and cause hepatocyte necrosis; N-acetylcysteine treats overdose by replenishing glutathione.', question: 'Why is N-acetylcysteine used to treat paracetamol overdose?', answer: 'It replenishes hepatic glutathione, which detoxifies the toxic metabolite NAPQI.' },
  { id: 'fr-6', topicId: 'free-radicals', fact: 'Glutathione (a tripeptide of glutamate, cysteine, and glycine) is the major intracellular antioxidant and detoxification cofactor, maintained in its reduced form by glutathione reductase using NADPH.', question: 'What provides the reducing power to regenerate reduced glutathione?', answer: 'NADPH, via glutathione reductase.' },
  { id: 'fr-7', topicId: 'free-radicals', fact: 'Glucose-6-phosphate dehydrogenase (G6PD) deficiency impairs NADPH production via the HMP shunt, limiting glutathione regeneration and predisposing red blood cells to oxidative hemolysis (e.g. triggered by fava beans or certain drugs).', question: 'Why does G6PD deficiency predispose to oxidative hemolysis?', answer: 'Reduced NADPH production limits regeneration of reduced glutathione, leaving RBCs vulnerable to oxidative stress.' },
  { id: 'fr-8', topicId: 'free-radicals', fact: 'Cytochrome P450 enzymes can be induced (e.g. by rifampin, phenobarbital, chronic alcohol) or inhibited (e.g. by cimetidine, ketoconazole, grapefruit juice), altering the metabolism and effective dose of many co-administered drugs.', question: 'Give an example of a drug that induces cytochrome P450 enzymes.', answer: 'Rifampin (also phenobarbital, chronic alcohol use).' },

  // ---- Molecular Biology Tools & Biotechnology ----
  { id: 'bt-1', topicId: 'biotech', fact: 'PCR (polymerase chain reaction) amplifies specific DNA sequences exponentially through cycles of denaturation, primer annealing, and extension by a heat-stable Taq polymerase.', question: 'What enzyme is essential to PCR, and why must it be heat-stable?', answer: 'Taq polymerase — it must survive repeated heating during the denaturation step of each cycle.' },
  { id: 'bt-2', topicId: 'biotech', fact: 'Southern blotting detects specific DNA sequences, Northern blotting detects RNA, and Western blotting detects proteins — all using a labeled probe/antibody after gel electrophoresis and transfer to a membrane.', question: 'What does Southern blotting detect?', answer: 'Specific DNA sequences.' },
  { id: 'bt-3', topicId: 'biotech', fact: 'Restriction endonucleases cut DNA at specific palindromic sequences, forming the basis of recombinant DNA technology by allowing genes to be cut and pasted into vectors like plasmids.', question: 'What type of DNA sequence do restriction enzymes typically recognize?', answer: 'Palindromic sequences.' },
  { id: 'bt-4', topicId: 'biotech', fact: 'DNA sequencing (Sanger method) uses dideoxynucleotides (ddNTPs) that lack a 3\'-OH group, causing chain termination when incorporated, allowing the DNA sequence to be read from fragment lengths.', question: 'Why do dideoxynucleotides terminate DNA synthesis during Sanger sequencing?', answer: 'They lack a 3\'-OH group needed to form the next phosphodiester bond, halting chain elongation.' },
  { id: 'bt-5', topicId: 'biotech', fact: 'ELISA (enzyme-linked immunosorbent assay) uses antibody-antigen binding with an enzyme-linked detection step to quantify a specific antigen or antibody in a sample, widely used for diagnostic testing (e.g. HIV screening).', question: 'What is the basic principle behind an ELISA test?', answer: 'Antigen-antibody binding coupled to an enzyme reaction that produces a measurable (usually colorimetric) signal.' },
  { id: 'bt-6', topicId: 'biotech', fact: 'Gene therapy delivers a functional gene copy using viral (e.g. adenovirus, AAV) or non-viral vectors to correct or compensate for a defective gene, as used experimentally in conditions like SCID and hemophilia.', question: 'What is a common type of vector used to deliver genes in gene therapy?', answer: 'Viral vectors, such as adeno-associated virus (AAV) or adenovirus.' },
  { id: 'bt-7', topicId: 'biotech', fact: 'CRISPR-Cas9 uses a guide RNA to direct the Cas9 endonuclease to a specific DNA sequence, creating a double-strand break that is then repaired, enabling targeted gene editing.', question: 'What guides Cas9 to its target DNA sequence in CRISPR gene editing?', answer: 'A guide RNA (gRNA) complementary to the target sequence.' },
  { id: 'bt-8', topicId: 'biotech', fact: 'Recombinant human insulin, produced in genetically engineered E. coli or yeast, was one of the first major products of recombinant DNA technology, replacing earlier animal-derived insulin.', question: 'What was one of the first major clinical products of recombinant DNA technology?', answer: 'Recombinant human insulin, produced in engineered bacteria (E. coli) or yeast.' },

  // ---- Water, Electrolyte & Acid-Base Balance (additional) ----
  { id: 'we-6', topicId: 'water-electrolyte', fact: 'The renin-angiotensin-aldosterone system (RAAS) raises blood pressure and sodium retention: renin (kidney) cleaves angiotensinogen to angiotensin I, ACE converts it to angiotensin II, which triggers aldosterone release and vasoconstriction.', question: 'What does angiotensin-converting enzyme (ACE) do?', answer: 'Converts angiotensin I to angiotensin II, a potent vasoconstrictor that also stimulates aldosterone release.' },
  { id: 'we-7', topicId: 'water-electrolyte', fact: 'ADH (vasopressin) increases water reabsorption by inserting aquaporin-2 channels in the renal collecting duct; its absence or resistance causes diabetes insipidus (central or nephrogenic).', question: 'How does ADH increase water reabsorption in the kidney?', answer: 'It inserts aquaporin-2 water channels into the collecting duct principal cells.' },
  { id: 'we-8', topicId: 'water-electrolyte', fact: 'The anion gap (Na⁺ − [Cl⁻ + HCO₃⁻]) helps classify metabolic acidosis: a high anion gap suggests added acid (e.g. ketoacidosis, lactic acidosis, toxins), while a normal gap suggests bicarbonate loss (e.g. diarrhea, renal tubular acidosis).', question: 'What does a high anion-gap metabolic acidosis suggest, versus a normal anion-gap acidosis?', answer: 'High gap: an unmeasured acid has been added (ketones, lactate, toxins). Normal gap: bicarbonate has been lost directly (e.g. diarrhea, RTA).' },
  { id: 'we-9', topicId: 'water-electrolyte', fact: 'Hyperkalemia causes peaked T waves and can progress to a sine-wave pattern and cardiac arrest; treatment includes calcium gluconate (membrane stabilization), insulin-glucose, and beta-agonists to shift potassium intracellularly.', question: 'What is the first-line treatment to stabilize the cardiac membrane in severe hyperkalemia?', answer: 'IV calcium gluconate.' },
  { id: 'we-10', topicId: 'water-electrolyte', fact: 'Hypoalbuminemia lowers plasma oncotic pressure, allowing fluid to shift into the interstitium — a key mechanism of edema in nephrotic syndrome, liver cirrhosis, and severe malnutrition (kwashiorkor).', question: 'How does hypoalbuminemia cause edema?', answer: 'It lowers plasma oncotic pressure, so fluid is not held in the vasculature and shifts into interstitial tissue.' },
  { id: 'we-11', topicId: 'water-electrolyte', fact: 'Magnesium deficiency often causes refractory hypokalemia and hypocalcemia that will not correct until magnesium is replaced, since Mg²⁺ is needed for normal Na⁺/K⁺-ATPase and PTH function.', question: 'Why does hypomagnesemia cause refractory hypokalemia?', answer: 'Magnesium is required for normal Na⁺/K⁺-ATPase function; without it, potassium cannot be properly retained even with replacement.' },
  { id: 'we-12', topicId: 'water-electrolyte', fact: 'SIADH causes euvolemic hyponatremia with concentrated urine despite low serum osmolality — from excess ADH unrelated to volume status, classically from small cell lung cancer, CNS disorders, or certain drugs.', question: 'What is the classic malignancy associated with SIADH?', answer: 'Small cell lung cancer (ectopic ADH production).' },

  // ---- Hormones (additional) ----
  { id: 'endo-7', topicId: 'endocrine', fact: 'Growth hormone acts partly directly and partly via IGF-1 (produced by the liver); excess in adults causes acromegaly, excess before growth-plate fusion causes gigantism.', question: 'Through what liver-derived factor does growth hormone exert many of its effects?', answer: 'Insulin-like growth factor 1 (IGF-1).' },
  { id: 'endo-8', topicId: 'endocrine', fact: 'Prolactin is under primarily inhibitory control by dopamine from the hypothalamus; dopamine antagonists (e.g. antipsychotics) commonly cause hyperprolactinemia and galactorrhea.', question: 'What hormone normally inhibits prolactin release?', answer: 'Dopamine.' },
  { id: 'endo-9', topicId: 'endocrine', fact: 'The hypothalamic-pituitary-thyroid axis follows negative feedback: TRH stimulates TSH, which stimulates T3/T4 release; rising T3/T4 suppress both TRH and TSH.', question: 'What suppresses TSH release in the thyroid axis?', answer: 'Rising T3/T4 levels, via negative feedback on the hypothalamus and pituitary.' },
  { id: 'endo-10', topicId: 'endocrine', fact: 'Cortisol follows a diurnal rhythm — highest in early morning, lowest around midnight — and its own negative feedback suppresses both CRH and ACTH.', question: 'When is cortisol typically highest during the day?', answer: 'Early morning, shortly after waking.' },
  { id: 'endo-11', topicId: 'endocrine', fact: 'Steroid and thyroid hormones act via intracellular/nuclear receptors that directly regulate gene transcription, unlike peptide hormones which act via cell-surface receptors and second messengers.', question: 'Why do steroid hormones have a slower onset of action than peptide hormones?', answer: 'They act via intracellular/nuclear receptors that regulate gene transcription, requiring new protein synthesis, rather than fast second-messenger cascades.' },
  { id: 'endo-12', topicId: 'endocrine', fact: 'Oxytocin (posterior pituitary) triggers uterine contraction and milk ejection reflex (let-down); like ADH, it is synthesized in the hypothalamus and stored/released from the posterior pituitary.', question: 'Where are oxytocin and ADH actually synthesized, despite being called posterior pituitary hormones?', answer: 'In the hypothalamus (supraoptic and paraventricular nuclei) — the posterior pituitary only stores and releases them.' },

  // ---- Molecular Biology (additional — cytogenetics & cancer biology) ----
  { id: 'mb-9', topicId: 'molbio', fact: 'Down syndrome (trisomy 21) is the most common autosomal trisomy compatible with life; risk rises sharply with maternal age, and most cases arise from meiotic nondisjunction.', question: 'What is the most common cause of Down syndrome?', answer: 'Meiotic nondisjunction of chromosome 21, giving trisomy 21 — strongly associated with advanced maternal age.' },
  { id: 'mb-10', topicId: 'molbio', fact: 'Klinefelter syndrome (47,XXY) causes tall stature, gynecomastia, and infertility in males; Turner syndrome (45,X0) causes short stature, webbed neck, and streak ovaries in females.', question: 'What karyotype causes Klinefelter syndrome, and what causes Turner syndrome?', answer: 'Klinefelter: 47,XXY. Turner: 45,X0 (monosomy X).' },
  { id: 'mb-11', topicId: 'molbio', fact: 'Oncogenes are mutated/overactive forms of normal proto-oncogenes (e.g. RAS, MYC) that drive uncontrolled cell growth — typically act in a dominant fashion, so one mutated allele is enough.', question: 'Do oncogene mutations typically need both alleles affected, like tumor suppressor genes?', answer: 'No — oncogenes act dominantly; a single activating mutation in one allele is usually sufficient.' },
  { id: 'mb-12', topicId: 'molbio', fact: "Tumor suppressor genes (e.g. p53, RB, BRCA1/2) normally restrain cell division or trigger apoptosis; both alleles must typically be lost or inactivated for cancer to develop (Knudson's two-hit hypothesis).", question: "What does Knudson's two-hit hypothesis describe?", answer: 'That both alleles of a tumor suppressor gene must be inactivated before cancer develops, unlike oncogenes which need only one hit.' },

  // ---- Organ Function Tests (additional — thyroid & tumor markers) ----
  { id: 'oft-9', topicId: 'organ-function', fact: 'TSH is the single best screening test for thyroid function in most patients — elevated TSH with low T4 indicates primary hypothyroidism; suppressed TSH with high T4 indicates hyperthyroidism.', question: 'What is the best initial screening test for thyroid dysfunction?', answer: 'TSH (thyroid-stimulating hormone).' },
  { id: 'oft-10', topicId: 'organ-function', fact: 'Tumor markers aid monitoring rather than primary diagnosis: AFP (hepatocellular carcinoma, germ cell tumors), CEA (colorectal cancer), CA-125 (ovarian cancer), PSA (prostate cancer), CA 19-9 (pancreatic cancer).', question: 'Which tumor marker is classically associated with ovarian cancer?', answer: 'CA-125.' },
  { id: 'oft-11', topicId: 'organ-function', fact: 'Alpha-fetoprotein (AFP) is also used in prenatal screening — elevated maternal serum AFP suggests neural tube defects, while low AFP is part of the triple/quad screen pattern seen in Down syndrome pregnancies.', question: 'What does an elevated maternal serum AFP suggest during pregnancy screening?', answer: 'An open neural tube defect (e.g. spina bifida, anencephaly).' },
  { id: 'oft-12', topicId: 'organ-function', fact: 'Serum amylase can also rise in non-pancreatic conditions (salivary gland disease, some tumors, renal failure) — lipase is preferred when pancreatitis is the specific concern due to higher specificity.', question: 'Why is lipase generally preferred over amylase to confirm pancreatitis?', answer: 'Lipase is more specific to the pancreas — amylase can also rise in salivary gland disease and other non-pancreatic conditions.' },

  // ---- Vitamins & Mineral Metabolism (additional minerals) ----
  { id: 'vit-13', topicId: 'vitamins', fact: 'Zinc deficiency impairs wound healing and immune function and causes a characteristic perioral and acral dermatitis; it is a cofactor for over 300 enzymes, including many zinc-finger transcription factors.', question: 'What clinical sign is classically associated with zinc deficiency?', answer: 'Perioral and acral (hands/feet) dermatitis, along with impaired wound healing and immune dysfunction.' },
  { id: 'vit-14', topicId: 'vitamins', fact: "Copper is a cofactor for lysyl oxidase (collagen/elastin cross-linking), ceruloplasmin, and cytochrome c oxidase; Wilson's disease (impaired copper excretion) causes copper accumulation in liver, brain, and cornea (Kayser-Fleischer rings).", question: "What is the classic eye finding in Wilson's disease?", answer: 'Kayser-Fleischer rings (copper deposition in the cornea).' },
  { id: 'vit-15', topicId: 'vitamins', fact: 'Selenium is a cofactor for glutathione peroxidase, linking it directly to antioxidant defense; severe deficiency is associated with Keshan disease, a form of cardiomyopathy.', question: 'Which antioxidant enzyme requires selenium as a cofactor?', answer: 'Glutathione peroxidase.' },
  { id: 'vit-16', topicId: 'vitamins', fact: "Iodine deficiency is the most common preventable cause of intellectual disability worldwide, causing goiter in adults and cretinism (growth failure, intellectual disability) if deficient during fetal development.", question: 'What is the most common preventable cause of intellectual disability worldwide?', answer: 'Iodine deficiency.' },
];
